// ------------------------------------------------ Markup: html``, ic() and setHtml(), the one way the viewer writes HTML
// docs/handbook/viewer.md §마크업 만들기. A value put into html`` is text unless it is Html the viewer made itself, so a
// note, a name or a PDF heading never becomes markup because one esc() was forgotten. Html is made only here (html``
// and ic()), and setHtml() is the one sink; src/limn/viewer/tests/test_viewer_markup.py holds every part to both.

// Markup the viewer built: html`` escaped every value in it, or ic() drew it from the bundled icon table. toString()
// gives the markup text (for tests and debugging); a string made from it is no Html, so setHtml() refuses it.
class Html {
  constructor(text) {
    this.text = text;
  }
  toString() {
    return this.text;
  }
}

// Tag for a template of markup. Returns Html whose literal parts are kept and whose values are escaped: an Html goes in
// as markup, an array as its items one after another (each by these rules), null and undefined as nothing, and
// anything else as escaped text (esc()), so false reads "false" (an aria-pressed value), not nothing. Write a
// condition as c?x:''. Values must sit in element content or a quoted attribute; esc() does not make an unquoted
// attribute or a URL attribute safe. Called as a function rather than a tag, it throws a TypeError.
function html(parts, ...values) {
  if (!Array.isArray(parts) || !Array.isArray(parts.raw)) throw new TypeError('html is a template tag: html`...`');
  let out = parts[0];
  for (let i = 0; i < values.length; i++) out += htmlValue(values[i]) + parts[i + 1];
  return new Html(out);
}

// The markup one html`` value stands for (see html()).
function htmlValue(v) {
  if (v instanceof Html) return v.text;
  if (Array.isArray(v)) return v.map(htmlValue).join('');
  if (v == null) return '';
  return esc(v);
}

// The Lucide icon n as an inline <svg> (same shape as the server's icon_svg(); CSS sets its size through .ic), or
// empty Html when the bundled table has no such icon. n is a name from this code, never user text.
function ic(n) {
  const b = ICONS[n];
  return new Html(
    b
      ? '<svg class="ic ic-' +
          n +
          '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' +
          b +
          '</svg>'
      : '',
  );
}

// Replaces el's children with markup. Throws a TypeError for anything but Html, so a string built by hand cannot
// reach the page through here. An empty element of the markup with data-cp (a code point in hex: ccHtml's box) then gets that
// character as its text through the DOM, which keeps what the HTML parser would drop or change (a NUL, a CR).
function setHtml(el, markup) {
  if (!(markup instanceof Html)) throw new TypeError('setHtml takes Html from html`` or ic()');
  el.innerHTML = markup.text;
  if (!markup.text.includes(' data-cp="')) return; // most markup has no box: no query
  for (const k of el.querySelectorAll('[data-cp]')) {
    const c = parseInt(k.getAttribute('data-cp') || '', 16);
    k.removeAttribute('data-cp');
    if (c >= 0 && c <= 0x10ffff && !(c >= 0xd800 && c <= 0xdfff)) k.textContent = String.fromCodePoint(c);
  }
}

// ------------------------------------------------ Characters that hide or reorder text (ADR-0029 D5, docs/superpowers/specs/2026-11-05-text-documents.md §결정 5)
// A bidirectional control can make a line read in another order than its source, and a zero-width, filler or control
// character can make two texts look the same (Trojan Source, CVE-2021-42574). Every place that shows a source's or a
// suggestion's text as it is - the text surface's lines, the excerpt under the ladder, a suggestion's diff, a rung's label -
// marks them, for every document kind, with this one repertoire, in one of two forms:
// - ccBox, ccHtml: the character stays in the text (a copy keeps it) inside an isolating span (.cc) that shows its name.
// - ccPlain: its name in angle brackets ('⟨U+202E⟩'), where only plain text can go (a label, a tooltip, a fallback view).
// The repertoire (CC_RANGES), by code point: Unicode's Default_Ignorable_Code_Point (the soft hyphen, the combining
// grapheme joiner, the Hangul fillers, the Khmer inherent vowels, the Mongolian variation selectors and vowel separator, the
// zero-width characters and bidirectional marks, the bidirectional embeddings, overrides and isolates, the word joiner and
// invisible operators, the deprecated format characters, the variation selectors, the byte-order mark, the shorthand and
// musical format controls, the tags), every C0 and C1 control but the tab and the line feed, the line and paragraph
// separators and the interlinear annotation characters. limn.pins.suggestion.HIDDEN_RANGES holds the same table for pins.md; a test
// ties the two and checks this one against the engine's own Unicode properties.
// A character a legitimate sequence needs is left as it is (ccKept). Nothing else is: a tag sequence (a subdivision flag)
// shows its tags by name.

const CC_RANGES = Object.freeze(
  [
    [0x00, 0x08],
    [0x0b, 0x1f],
    [0x7f, 0x9f],
    [0xad, 0xad],
    [0x34f, 0x34f],
    [0x61c, 0x61c],
    [0x115f, 0x1160],
    [0x17b4, 0x17b5],
    [0x180b, 0x180f],
    [0x200b, 0x200f],
    [0x2028, 0x202e],
    [0x2060, 0x206f],
    [0x3164, 0x3164],
    [0xfe00, 0xfe0f],
    [0xfeff, 0xfeff],
    [0xffa0, 0xffa0],
    [0xfff0, 0xfffb],
    [0x1bca0, 0x1bca3],
    [0x1d173, 0x1d17a],
    [0xe0000, 0xe0fff],
  ].map((r) => Object.freeze(r)),
);
// The repertoire as one regular expression over code points (a supplementary character is one match, never two halves).
const CC_RE = new RegExp(
  '[' +
    CC_RANGES.map(([a, b]) => '\\u{' + a.toString(16) + '}' + (b > a ? '-\\u{' + b.toString(16) + '}' : '')).join('') +
    ']',
  'gu',
);
const CC_ANY = new RegExp(CC_RE.source, 'u'); // the same, for a test that keeps no state
// The scripts whose ordinary text puts a zero-width joiner or non-joiner between two of its letters (Persian, Indic
// conjuncts and half forms, Syriac, Mongolian), an emoji's pictograph, a Han ideograph and a Mongolian letter.
const CC_JOINING =
  /[\p{sc=Arabic}\p{sc=Syriac}\p{sc=Mongolian}\p{sc=Devanagari}\p{sc=Bengali}\p{sc=Gurmukhi}\p{sc=Gujarati}\p{sc=Oriya}\p{sc=Tamil}\p{sc=Telugu}\p{sc=Kannada}\p{sc=Malayalam}\p{sc=Sinhala}]/u;
const CC_PICTO = /\p{Extended_Pictographic}/u,
  CC_HAN = /\p{sc=Han}/u,
  CC_MONGOLIAN = /\p{sc=Mongolian}/u;
// The name a marked character shows: a C0 control's picture (the U+2400 block), DEL's, else its code point (U+202E,
// U+E0041). Pure.
function ccName(c) {
  if (c < 0x20) return String.fromCodePoint(0x2400 + c);
  if (c === 0x7f) return '␡';
  return 'U+' + c.toString(16).toUpperCase().padStart(4, '0');
}
// The code point just before index i of s (a surrogate pair whole), or -1 at its start; and the one at index i, or -1 past it.
function ccBefore(s, i) {
  if (i <= 0) return -1;
  const lo = s.charCodeAt(i - 1);
  if (i >= 2 && lo >= 0xdc00 && lo <= 0xdfff) {
    const hi = s.charCodeAt(i - 2);
    if (hi >= 0xd800 && hi <= 0xdbff) return s.codePointAt(i - 2) ?? -1;
  }
  return lo;
}
function ccAt(s, i) {
  return i < s.length ? (s.codePointAt(i) ?? -1) : -1;
}
function ccIn(c, re) {
  return c >= 0 && re.test(String.fromCodePoint(c));
}
// Whether the marked character c at index i of s is one a legitimate sequence needs, and so is left as it is - the
// exceptions, each tested:
// - a byte-order mark at the very start of a file (first: s is its line 1): the encoding's mark, not text;
