  if (o.source) {
    const old = sourceEntry(o.source);
    if (old) {
      if (old.place === NOTICE_PLACE.LINE && sameWords(old, text, kind)) return old;
      endNotice(old, true);
    }
  }
  if (newsDupe(keys, rank, null)) return null;
