    ...o,
    msg: o.literal ? String(msg) : trMsg(msg),
    kind,
    act: act || null,
    place: NOTICE_PLACE.LINE,
    pending: false,
    alert: kind === NOTICE_KIND.ERR || !!o.alert,
    dot: noticeDot(o.dot || '', SIDE_OPEN),
