// A document link's description: name, path, what kind of document it is, and its build state. The link is user text
// (translate="no", the name), so the UI words are translated here.
function docTip(d) {
  return (
    d.name +
    ' · ' +
    d.path +
    (d.view_only ? tr(' · 보기 전용 PDF(줄 번호 없이 쪽·영역으로 핀을 남깁니다)') : '') +
    (isFigureKind(d.kind) ? ' · ' + tr('그림 문서(드래그하면 요소와 그 요소를 그린 코드 줄을 찾습니다)') : '') +
    (d.building ? tr(' · 빌드 중') : d.stale_build ? tr(' · 원고가 이 PDF보다 새롭습니다(그 탭에서 [PDF 재빌드])') : '')
  );
}
// The marks of a document link: its name (.lbl, trimmed to its cap height by CSS as the view tabs' words) and page count.
function docLinkInner(d) {
  const count = d.n_pages ? html`<span class="doc-link-count">${tl('{n}쪽', { n: d.n_pages })}</span>` : '';
  return html`<span class="lbl">${d.name}</span>${count}`;
}
// What a link's or a popover row's inside was last drawn from, so a redraw that changes nothing writes nothing.
const DOC_DRAWN = new WeakMap();
// Sets the inside of el to markup m, drawn from key - unless it was drawn from key already. el itself stays: one that has the
// focus keeps it, and no focusout or focusin is sent.
function docInner(el, m, key) {
  if (DOC_DRAWN.get(el) === key) return;
  setHtml(el, m);
  DOC_DRAWN.set(el, key);
}
// Sets attribute a of el to v when it is not v already (an unchanged write still reaches the MutationObservers).
function setAttr(el, a, v) {
  if (el.getAttribute(a) !== v) el.setAttribute(a, v);
}
// Draws the document choosers: the select, the nav bar's links, the phone's position button (drawPos), an open navigation
// sheet's rows and an open documents popover's. A document's name is user text (translate="no"); the UI words beside it (build
// state, page count, the description) are translated here. With the same documents in the same order (a redraw by polling)
// each link is updated in place - only what changed - so a link or [+N] (#doc-more, after the links) that has the focus keeps
// the same node; otherwise the links are made again in front of [+N] and a link that had the focus gives it to its document's
// new link. Then the row is fitted (docFit).
function drawDocTabs() {
  const box = $('#doc-select');
  setHtml(
    box,
    html`${DOCS.map((d) => html`<option translate="no" value="${d.key}">${d.name}${d.building ? tr(' · 빌드 중') : d.stale_build ? tr(' · 원고 수정됨') : ''}</option>`)}`,
  );
  if (DOC) box.value = DOC;
  const row = $('#doc-links'),
    more = $('#doc-more'),
    had = document.activeElement,
    old = [...row.querySelectorAll(':scope>[data-doc]')];
  const same = old.length === DOCS.length && old.every((a, i) => a.dataset.doc === DOCS[i].key);
  let was = null;
  if (!same) {
    was = had && had !== more && row.contains(had) ? had.dataset.doc : null;
    old.forEach((a) => a.remove());
    const links = document.createElement('div');
    setHtml(links, html`${DOCS.map((d) => html`<button translate="no" data-act="doc" data-doc="${d.key}"></button>`)}`);
    more.before(...links.children);
  }
  ([...row.querySelectorAll(':scope>[data-doc]')]).forEach((a, i) => {
    const d = DOCS[i];
    setAttr(a, 'aria-current', d.key === DOC ? 'page' : 'false');
    setAttr(a, 'title', docTip(d));
    docInner(a, docLinkInner(d), d.name + '\u0001' + (d.n_pages || ''));
  });
  drawPos();
  docFit();
  const back = was
    ? ([...row.querySelectorAll(':scope>[data-doc]')]).find((a) => a.dataset.doc === was && !a.hidden)
    : null;
  if (back) back.focus({ preventScroll: true });
  if ($('#nav-sheet').open) drawDocsMenu();
  if (!$('#doc-pop').hidden) drawDocMenu();
}

// ---- The document row's fit (docs/handbook/viewer.md §문서 링크가 넘칠 때)
// Which links the row shows, as indices into w: every one when they all fit room - w are the links' widths, gap the row's gap -
// else the first k in order with [+N] after them (moreW(N): its width saying N), k as large as fits, and the current
// document's link (index cur, -1 for none) always among them: when it would be hidden it takes the k-th place. None ([]) when
// not even one link and [+N] fit: the row is then a single chooser (docFit). Pure.
function docTabsShown(w, gap, cur, room, moreW) {
  const n = w.length,
    all = w.map((_, i) => i),
    width = (a) => a.reduce((s, i) => s + w[i], 0) + gap * Math.max(0, a.length - 1),
    fits = (x) => x <= room + 0.01;
  if (fits(width(all))) return all;
  for (let k = n - 1; k >= 1; k--) {
    const a = all.slice(0, k);
    if (cur >= k) a[k - 1] = cur;
    if (fits(width(a) + gap + moreW(n - k))) return a;
  }
  return [];
}
// How the chooser stands when no link and [+N] fit together: 'name' - the current document's name, shortened to an ellipsis
// as room needs - when room holds the whole name or at least the chooser's own width (chrome: padding, gap, chevron) and three
// em of name; else 'icon'. Pure.
function docChooser(room, full, chrome, em) {
  return room + 0.01 >= Math.min(full, chrome + 3 * em) ? 'name' : 'icon';
}
let DOC_FIT = ''; // the row's last fit: a measure that changes nothing writes nothing and re-fits nothing
// Fits the nav bar's document row to the room the bar leaves it, down a ladder in which nothing is ever cut:
// (a) as many whole links as fit, in DOCS order, the current one always among them, and [+N] for the N left out
//     (docTabsShown) - or every link and no button;
// (b) when not even the current link and [+N] fit: one chooser, [+N]'s button (#doc-more, data-fit="name"), saying the
//     current document's name - ellipsis as needed - and opening the same popover;
// (c) when (b) could not show three em of the name: the same chooser as an icon (data-fit="icon").
// The room is the bar's content width less every other control at its own width and the gaps between them, three of them
// counted as they would stand: the search at its folded magnifier (the field gives way before the links, as it gives way
// before every neighbour - searchFit takes what the row leaves), and at their whole widths the paper's name (up to its
// max-width: the links give way before it is shortened) and the short band's status line (it gives way last). The row's
// least width is its content's (frame.css), so below (c) the bar's neighbours give way instead, each only after the row is
// down to its icon: the paper's name shortens (it may shrink), and the short band's status line - which never shrinks, as
// the search measures it whole - drops its words, whole or not at all: a stub of one or two letters said less than nothing
// (its icon and action stay, and its spoken label is its own node).
// Measured with every link shown, then each hidden or shown whole. Nothing that has the focus is hidden to be measured (a
// hidden control loses it): the links are measured all shown, the button where it stands; a link or the button that has the
// focus and is left out gives it to the button or the current link. When the fit changes the search is fitted again; an
// open popover is placed again under its button (which may have moved), or shuts when the button has gone. Where the row is
// not drawn (the phone, one document) nothing is.
function docFit() {
  const row = $('#doc-links'),
    more = $('#doc-more'),
    nav = $('#doc-nav'),
    lbl = more.querySelector('.lbl'),
    tabs = [...row.querySelectorAll(':scope>[data-doc]')],
    px = (v) => parseFloat(v) || 0,
    had = document.activeElement;
  let fit = '',
    drop = false;
  const st = $('#status');
  st.classList.remove('st-words-off'); // measured with its words; dropped again below when they do not fit
  if (row.getClientRects().length && tabs.length > 1) {
    const cs = getComputedStyle(nav),
      rs = getComputedStyle(row);
    // its whole width: laid out for the moment as it would stand unshrunk (up to its max-width), to the fraction of a pixel
    const whole = (k) => {
      k.style.flex = 'none';
      const x = k.getBoundingClientRect().width;
      k.style.flex = '';
      return x;
    };
    let used = 0,
      n = 0;
    for (const k of [...nav.children]) {
      if (k === row || !k.getClientRects().length) continue;
      const m = getComputedStyle(k);
      n++;
      if (k.id === 'doc-search') {
        used += px(getComputedStyle($('#search-open')).width);
        continue;
      } // its margin is the bar's one flexible gap
      if (k.id === 'paper-identity' || k.id === 'status') used += whole(k);
      else used += k.getBoundingClientRect().width;
      if (!k.matches('#nav-page,#nav-side')) used += px(m.marginLeft) + px(m.marginRight);
    } // those two stand after the flexible gap
    const room =
      nav.clientWidth -
      px(cs.paddingLeft) -
      px(cs.paddingRight) -
      px(cs.columnGap) * n -
      used -
      px(rs.marginLeft) -
      px(rs.marginRight);
    tabs.forEach((a) => {
      a.hidden = false;
    });
    const ms = getComputedStyle(more),
      mm = px(ms.marginLeft) + px(ms.marginRight); // the button's width counts its margins (frame.css)
    const w = tabs.map((a) => a.getBoundingClientRect().width),
      gap = px(rs.columnGap),
      seen = new Map(),
      was = more.hidden;
    const as = (mode, text) => {
      more.dataset.fit = mode;
      lbl.textContent = text;
      more.style.maxWidth = '';
    };
    const width = (mode, text) => {
      as(mode, text);
      more.hidden = false;
      const x = more.getBoundingClientRect().width + mm;
      more.hidden = was;
      return x;
    };
    const moreW = (N) => {
      if (!seen.has(N)) seen.set(N, width('more', '+' + N));
      return seen.get(N);
    };
    const cur = Math.max(
        0,
        tabs.findIndex((a) => a.dataset.doc === DOC),
      ),
      d = docInfo(tabs[cur].dataset.doc || '') || DOCS[cur];
    const shown = docTabsShown(w, gap, cur, room, moreW),
      N = tabs.length - shown.length;
    let mode = 'more',
      cap = '';
    if (!shown.length) {
      const full = width('name', d.name),
        chrome = width('name', '');
      mode = docChooser(room, full, chrome, px(getComputedStyle(lbl).fontSize));
      if (mode === 'name' && full > room) cap = Math.floor(room - mm) + 'px';
      drop = mode === 'icon' && nav.contains(st) && width('icon', '') > room + 0.5;
    } // the short band's status line gives way: all its words
    tabs.forEach((a, i) => {
      a.hidden = !shown.includes(i);
    });
    as(mode, mode === 'more' ? '+' + N : mode === 'name' ? d.name : '');
    more.style.maxWidth = cap;
    if (mode === 'more') {
      more.setAttribute('aria-label', tl('+{n} 문서 더 보기', { n: N }));
      more.removeAttribute('title');
    } else {
      more.setAttribute('aria-label', d.name + ' — ' + tl('문서 {n}개 중 고르기', { n: DOCS.length }));
      more.setAttribute('title', docTip(d));
    }
    more.hidden = mode === 'more' && !N;
    fit = [mode, shown.map((i) => tabs[i].dataset.doc).join(), N, cap, d.name, drop].join('|');
  } else {
    tabs.forEach((a) => {
      a.hidden = false;
    });
    more.hidden = true;
  }
  st.classList.toggle('st-words-off', drop);
  const lost =
    had instanceof HTMLElement && (row.contains(had) ? had.hidden : !more.hidden ? false : $('#doc-pop').contains(had));
  if (more.hidden) closeDocMenu(false);
  if (lost) {
    const to = more.hidden ? tabs.find((a) => a.getAttribute('aria-current') === 'page') : more;
    if (to) to.focus({ preventScroll: true });
  }
  if (fit !== DOC_FIT) {
    DOC_FIT = fit;
    searchFit();
  }
  placeDocMenu();
}
// Re-fits once a frame when the bar or a control beside the row changes size (the window, the pin panel, the page count, the
// status line in the short band, the search) - never on the row's own size, which the fit sets - and when a font arrives.
let DOC_FIT_FRAME = 0;
function docFitSoon() {
  if (!DOC_FIT_FRAME)
    DOC_FIT_FRAME = requestAnimationFrame(() => {
      DOC_FIT_FRAME = 0;
      docFit();
    });
}
if (window.ResizeObserver) {
  const o = new ResizeObserver(docFitSoon);
  o.observe($('#doc-nav'));
  o.observe($('#status'));
  for (const k of $$('#doc-nav>*')) if (k.id !== 'doc-links') o.observe(k);
}
document.fonts.addEventListener('loadingdone', docFit);
// The row is a scroll box only for how it is painted (frame.css): it never scrolls. The current link's bar reaches 1px under
// it, which a browser lets keys scroll after a press in the row (the links moved up 1px) - undone at once - and which made
// Firefox give the row a Tab stop of its own, a ring round all the links (index.html takes it out of the Tab order).
$('#doc-links').addEventListener(
  'scroll',
  (e) => {
    const r = e.currentTarget;
    if (r.scrollTop || r.scrollLeft) {
      r.scrollTop = 0;
      r.scrollLeft = 0;
    }
  },
  { passive: true },
);

// ---- The documents popover ([+N] or the chooser, docs/handbook/viewer.md §문서 링크가 넘칠 때)
// Every document in DOCS order, one row each: the current one's check, the name (user text) with its build state (docState),
// the page count and, for the first nine, the Alt+number that picks it. Choosing a row is a document link's click (data-act
// "doc": switchDoc). With nine documents or more a field on top filters the rows by name or path.
// Draws the popover's rows. A redraw with the same documents in the same order (polling) updates each row in place - only
// what changed - so a focused row keeps its node and the focus, and the filter and the list's scroll stay.
function drawDocMenu() {
  const list = $('#doc-pop-list'),
    old = [...list.children];
  if (!(old.length === DOCS.length && old.every((r, i) => r.dataset.doc === DOCS[i].key)))
    setHtml(
      list,
      html`${DOCS.map((d) => html`<button class="dp-row" role="option" data-act="doc" data-doc="${d.key}"></button>`)}`,
    );
  ([...list.children]).forEach((r, i) => {
    const d = DOCS[i],
      on = d.key === DOC,
      st = d.building ? 'spin' : d.stale_build ? 'dot' : '';
    r.classList.toggle('on', on);
    setAttr(r, 'aria-selected', String(on));
    setAttr(r, 'tabindex', on ? '0' : '-1');
    docInner(
      r,
      html`<span class="dp-c">${on ? ic('check') : ''}</span><span class="dp-n"><span class="dp-t" translate="no">${d.name}</span>${docState(d)}</span><span class="dp-p">${d.n_pages ? tl('{n}쪽', { n: d.n_pages }) : ''}</span><span class="dp-k">${i < 9 ? 'Alt+' + (i + 1) : ''}</span>`,
      [d.name, d.n_pages || '', on, st, LANG].join('\u0001'),
    );
  });
  docMenuFilter();
}
// Shows the rows whose document's name or path holds the field's text (case folded, as the outline's search), and says so
// when none does.
function docMenuFilter() {
  const q = ($('#doc-pop-in')).value.trim().toLowerCase();
  let n = 0;
  for (const r of [...$('#doc-pop-list').children]) {
    const d = docInfo(r.dataset.doc || '');
    r.hidden = !!q && !(d && (d.name + ' ' + d.path).toLowerCase().includes(q));
    if (!r.hidden) n++;
  }
  $('#doc-pop-none').hidden = n > 0;
}
// Opens the popover under its button. A mouse or a keyboard gets the focus in the filter when there is one; touch - no
// keyboard comes up - and a list without it get the current document's row, scrolled into view.
function openDocMenu() {
  const pop = $('#doc-pop'),
    f = $('#doc-pop-in');
  hideTip();
  closePageList(false);
  f.hidden = DOCS.length < 9;
  f.value = '';
  $('#doc-more').setAttribute('aria-expanded', 'true');
  pop.hidden = false;
  drawDocMenu();
  placeDocMenu();
  const row = $('#doc-pop-list [aria-selected=true]');
  if (row) row.scrollIntoView({ block: 'nearest' });
  const to = !f.hidden && !MQ_COARSE.matches ? f : row || pop;
  to.focus({ preventScroll: true });
}
// Puts the open popover under its button, its left edge on the button's and inside the window by 8px, and lets it grow down to
// 8px above the window's bottom (--dp-room); its list scrolls inside that. docFit calls it after every fit, so the popover
// follows its button when the bar changes (the window, the pin panel, the outline).
function placeDocMenu() {
  const pop = $('#doc-pop'),
    more = $('#doc-more');
  if (pop.hidden) return;
  if (!more.getClientRects().length) {
    closeDocMenu(false);
    return;
  }
  const r = more.getBoundingClientRect(),
    top = Math.round(r.bottom) + 4,
    w = pop.offsetWidth;
  pop.style.left = Math.max(8, Math.min(Math.round(r.left), innerWidth - 8 - w)) + 'px';
  pop.style.top = top + 'px';
  pop.style.setProperty('--dp-room', Math.max(0, innerHeight - 8 - top) + 'px');
}
// Shuts the popover; back gives the focus back to its button (Esc, a choice, Shift+Tab out of it).
function closeDocMenu(back) {
  const pop = $('#doc-pop'),
    more = $('#doc-more');
  if (pop.hidden) return;
  pop.hidden = true;
  more.setAttribute('aria-expanded', 'false');
  if (back && more.getClientRects().length) more.focus({ preventScroll: true });
}
// The button's click: opens the popover, or shuts it when it is open.
function toggleDocMenu() {
  if ($('#doc-pop').hidden) openDocMenu();
  else closeDocMenu(false);
}
// The nav bar's next stop after the popover's button, in its order (DOM order, as Tab goes): what Tab out of the popover
// lands on. Null when the button is the bar's last.
function docMenuNext() {
  const more = $('#doc-more'),
    stops = ([...$('#doc-nav').querySelectorAll('button,input,select,a[href],[tabindex]')]).filter(
      (e) =>
        e === more ||
        (e.tabIndex >= 0 &&
          !(e).disabled &&
          e.getClientRects().length > 0 &&
          getComputedStyle(e).visibility !== 'hidden'),
    );
  return stops[stops.indexOf(more) + 1] || null;
}
// Keys: ↓ on the button opens the popover (Enter and Space are its click). In the filter ↓ goes to the current row (the first
// shown when it is filtered out) and Enter chooses the first row shown; on a row ↓/↑ move one row, Home/End to the ends, ↑ on
// the first goes back to the filter. Alt+1…9 picks that document from anywhere in the popover, the filter too (the shortcut
// is otherwise not taken inside a text field). Tab leaves the popover forward: from the filter to the list's row, from a row
// out - the popover shuts and the focus goes to the bar's next stop after the button; Shift+Tab goes back: from a row to the
// filter, from the filter (or a row with no filter) out to the button, the popover shut. Esc is the viewer's (events.js): it
// shuts the popover with the focus on the button.
$('#doc-more').addEventListener('keydown', (e) => {
  if (e.key === 'ArrowDown' && !e.altKey) {
    e.preventDefault();
    if ($('#doc-pop').hidden) openDocMenu();
  }
});
$('#doc-pop').addEventListener('keydown', (e) => {
  const t = e.target,
    f = $('#doc-pop-in');
  if (imeKey(e)) return;
  const rows = ([...$('#doc-pop-list').children]).filter((r) => !r.hidden),
    field = !f.hidden;
  if (e.altKey && !e.ctrlKey && !e.metaKey && /^Digit[1-9]$/.test(e.code || '')) {
    const d = DOCS[+e.code.slice(5) - 1];
    e.preventDefault();
    e.stopPropagation();
    if (d) {
      closeDocMenu(true);
      switchDoc(d.key);
    }
    return;
  }
  if (e.key === 'Tab' && !e.ctrlKey && !e.altKey && !e.metaKey) {
    e.preventDefault();
    if (e.shiftKey) {
      if (t !== f && field) f.focus();
      else closeDocMenu(true);
      return;
    }
    if (t === f && rows.length) {
      (rows.find((r) => r.classList.contains('on')) || rows[0]).focus();
      return;
    }
    const next = docMenuNext();
    closeDocMenu(!next);
    if (next) next.focus();
    return;
  }
  if (t === f) {
    if (e.key === 'ArrowDown' && rows.length) {
      e.preventDefault();
      (rows.find((r) => r.classList.contains('on')) || rows[0]).focus();
    } else if (e.key === 'Enter' && rows.length) {
      e.preventDefault();
      rows[0].click();
    }
    return;
  }
  const i = rows.indexOf(t);
  if (i < 0) return;
  if (e.key === 'ArrowUp' && i === 0 && field) {
    e.preventDefault();
    f.focus();
    return;
  }
  const to = { ArrowDown: i + 1, ArrowUp: i - 1, Home: 0, End: rows.length - 1 }[e.key];
  if (to === undefined) return;
  e.preventDefault();
  const r = rows[Math.max(0, Math.min(rows.length - 1, to))];
  r.focus();
  r.scrollIntoView({ block: 'nearest' });
});
$('#doc-pop-in').addEventListener('input', docMenuFilter);
// The focus moving to a control outside the popover and its button (a click on another control, a shortcut that moves it)
// shuts it; a press anywhere outside them shuts it too (the press still does what it does). Focus that goes nowhere (the
// window losing it) leaves it open.
$('#doc-pop').addEventListener('focusout', (e) => {
  const to = e.relatedTarget;
  if (to && !$('#doc-pop').contains(to) && !$('#doc-more').contains(to)) closeDocMenu(false);
});
document.addEventListener(
  'pointerdown',
  (e) => {
    const t = e.target;
    if (!$('#doc-pop').hidden && !$('#doc-pop').contains(t) && !$('#doc-more').contains(t)) closeDocMenu(false);
  },
  true,
);
addEventListener('resize', placeDocMenu);

// One changes-view visit owns the selected commit, source text and request sequence. overlay is a figure document's two
// builds from /api/revisions (null for any other document), side the one its overlay shows, history whether it has commits.
// Issue #188: base is a range's old side ('' for one commit against its first parent); rows the loaded commits (newest
// first, REVISION_PAGE a page) of rowsDoc, more whether older ones remain; range the quick range and its ends (RevRange);
// seen this browser's last-seen commit of the document, seenState what the server said of it (SEEN_STATE), seenN how many
// commits it compares with the newest and seenIds which (the server's count, never the list's positions); rangeIds the
// commits the shown range compares (the server's commit_ids; null until it answers), rangeBase its old side; listOpen
// whether the phone shows every loaded row; rangeLine the range's summary for the status line, and rangeN its commit and file
// counts (the rendered compare's status line takes them, md-compare.js mdcStatus).
const REV = {
  seq: 0,
  files: [],
  whole: '',
  commit: '',
  sourceCommit: '',
  format: DIFF_FORMAT.PDF,
  scope: null,
  other: '',
  target: null,
  pdfCommit: '',
  back: null,
  overlay: null,
  side: OVERLAY_SIDE.CUR,
  history: false,
  base: '',
  rows: [],
  rowsDoc: '',
  more: false,
  range: { mode: RANGE_MODE.ONE, start: '', end: '', endSet: false },
  seen: null,
  seenState: SEEN_STATE.NONE,
  seenN: 0,
  seenIds: new Set(),
  rangeIds: null,
  rangeBase: '',
  listOpen: false,
  rangeLine: '',
  rangeN: null,
  want: null,
};
const REVISION_PAGE = 30; // rows of one /api/revisions page (the server's history window is 500, api.md)
const REVISION_RECENT = 12; // the commits [변경 보기] picks a pin's commit among - the server resolves a close_ref among the same
const REVISION_PHONE_ROWS = 5; // rows the phone's list shows before [더 보기]
// v0.3 (docs/handbook/viewer.md §변경 보기): a pin's view of a commit. REV.scope is the source diff's scope object
// ({mode:'pin'|'commit', source, hunks, other, ...}); REV_PDF holds the comparison PDF's toggle - whole commit or only this pin.
const REV_SCOPE = { whole: false, partial: false, fallback: false };
const REV_PDF = {
  doc: null,
  loading: null,
  observer: null,
  tasks: new Set(),
};
function revisionFiles(patch) {
  const starts = [];
  const re = /^diff --git .+$/gm;
  let m;
  while ((m = re.exec(patch)) !== null) starts.push({ at: m.index, head: m[0] });
  return starts.map((s, i) => {
    const n = s.head.lastIndexOf(' b/');
    return {
      name: n >= 0 ? s.head.slice(n + 3) : tl('파일 {n}', { n: i + 1 }),
      text: patch.slice(s.at, i + 1 < starts.length ? starts[i + 1].at : undefined),
    };
  });
}
// A patch as Html of numbered lines (file, hunk, add, del, context, meta). The code itself is the manuscript's text, so
// it is translate="no"; the lines are text, each character that would hide or reorder a line in its box (ccHtml) - a
// change a person reviews never reads as another text. The CR a CRLF file's line ends in is that line end, not text: left out.
function renderRevisionDiff(patch) {
  const lines = String(patch || '').split('\n');
  if (lines[lines.length - 1] === '') lines.pop();
  let oldLine = null,
    newLine = null,
    inHunk = false;
  return html`${lines.map((line) => {
    let kind = 'meta',
      number = '';
    if (line.startsWith('diff --git ')) {
      kind = 'file';
      inHunk = false;
      oldLine = newLine = null;
    } else if (line.startsWith('@@ ')) {
      kind = 'hunk';
      inHunk = true;
      const at = /^@@ -(\d+)(?:,\d+)? \+(\d+)/.exec(line);
      oldLine = at ? Number(at[1]) : null;
      newLine = at ? Number(at[2]) : null;
    } else if (!inHunk && (line.startsWith('--- ') || line.startsWith('+++ '))) {
      kind = 'meta';
    } else if (line.startsWith('+')) {
      kind = 'add';
      if (newLine !== null) number = newLine++;
    } else if (line.startsWith('-')) {
      kind = 'del';
      if (oldLine !== null) number = oldLine++;
    } else if (line.startsWith(' ')) {
      kind = 'context';
      if (newLine !== null) {
        number = newLine++;
        if (oldLine !== null) oldLine++;
      }
    }
    return html`<span class="rd-line rd-${kind}"><span class="rd-no" aria-hidden="true">${number}</span><span class="rd-code" translate="no">${ccHtml(line.endsWith('\r') ? line.slice(0, -1) : line)}</span></span>`;
  })}`;
}
function renderRevisionFile() {
  const v = $('#revision-file').value,
    i = Number(v);
  setHtml(
    $('#revision-diff'),
    renderRevisionDiff(v === 'all' ? REV.whole : (REV.files[i] && REV.files[i].text) || REV.whole),
  );
}
// The rest of the commit, folded under one control (v0.3). Hidden when the pin owns the whole commit or the view is not a pin's.
function drawRevisionOther(sc) {
  const b = $('#revision-other-toggle'),
    o = $('#revision-other');
  o.hidden = true;
  o.replaceChildren();
  b.setAttribute('aria-expanded', 'false');
  REV.other =
    sc && sc.mode === SCOPE_MODE.PIN
      ? String(sc.other_diff || '') +
        (sc.other_truncated
          ? '\n\n' + tr('변경 내용이 커서 앞부분만 표시했습니다. 저장소에서 전체 diff를 확인하세요.')
          : '')
      : '';
  b.hidden = !REV.other;
  if (REV.other) b.querySelector('span').textContent = tl('이 커밋의 다른 변경 {n}곳', { n: sc.other });
}
function toggleRevisionOther() {
  const b = $('#revision-other-toggle'),
    o = $('#revision-other'),
    open = b.getAttribute('aria-expanded') !== 'true';
  b.setAttribute('aria-expanded', String(open));
  o.hidden = !open;
  if (open && !o.firstChild) setHtml(o, renderRevisionDiff(REV.other));
}
// [커밋 전체 비교]: shown only for the PDF of a pin that owns part of the commit, and not after a fallback (there is nothing to switch to).
function syncRevisionWhole() {
  const b = $('#revision-whole');
  b.hidden = !(
    REV.format === DIFF_FORMAT.PDF &&
    revisionPinFor(REV.commit) &&
    REV_SCOPE.partial &&
    !REV_SCOPE.fallback
  );
  b.setAttribute('aria-pressed', String(REV_SCOPE.whole));
}
// The pin whose hunks a commit's view is scoped to: only the commit picked for the pin ([변경 보기]); any other commit
// chosen in the list is shown whole (review M1 - another commit's lines are not this pin's), and so is a range (#188:
// pin scoping and ranges do not combine yet; the server refuses pin with base).
function revisionPinFor(id) {
  const tg = REV.target;
  return tg && !tg.region && tg.commit && id === tg.commit && !REV.base ? tg : null;
}
function setRevisionWhole(on) {
  REV_SCOPE.whole = !!on;
  ++REV.seq;
  REV.pdfCommit = '';
  clearRevisionPdf();
  $('#revision-warning').hidden = true;
  setRevisionFormat(DIFF_FORMAT.PDF);
}
function revisionCurrent(seq, k, id) {
  return seq === REV.seq && k === DOC && id === REV.commit && document.body.classList.contains('revision-open');
}
/** Release comparison rendering and PDF.js resources on visit or scope change. */
function clearRevisionPdf() {
  disposeRevisionZoom();
  if (REV_PDF.observer) {
    REV_PDF.observer.disconnect();
    REV_PDF.observer = null;
  }
  REV_PDF.tasks.forEach((t) => {
    try {
      t.cancel();
    } catch (e) {}
  });
  REV_PDF.tasks.clear();
  if (REV_PDF.loading) {
    try {
      void REV_PDF.loading.destroy().catch(() => {});
    } catch (e) {}
    REV_PDF.loading = null;
  }
  REV_PDF.doc = null;
  $('#revision-pdf').replaceChildren();
}
// The format a document's changes show for the one asked (docs/handbook/viewer.md §변경 보기): the source diff when asked; a
// document drawn from Markdown (drawn) its rendered compare otherwise; the source diff always for another document with no
// comparison PDF (source: one the browser draws, a text document); otherwise a figure document's overlay of two builds, and a
// LaTeX document's comparison PDF - never the overlay. Pure.
function revisionFormatFor(asked, figure, source, drawn) {
  if (asked === DIFF_FORMAT.SOURCE) return DIFF_FORMAT.SOURCE;
  if (drawn && !figure) return DIFF_FORMAT.RENDERED;
  return source && !figure ? DIFF_FORMAT.SOURCE : figure ? DIFF_FORMAT.OVERLAY : DIFF_FORMAT.PDF;
}
// Shows REV.format: the pressed tab, the pane, [이전 | 지금] with the overlay, and the overlay's status line on a figure
// document (its source diff has none). Loads nothing.
function drawRevisionFormat() {
  $('#revision-pdf-tab').setAttribute('aria-pressed', String(REV.format === DIFF_FORMAT.PDF));
  $('#revision-overlay-tab').setAttribute('aria-pressed', String(REV.format === DIFF_FORMAT.OVERLAY));
  $('#revision-source-tab').setAttribute('aria-pressed', String(REV.format === DIFF_FORMAT.SOURCE));
  $('#revision-rendered-tab').setAttribute('aria-pressed', String(REV.format === DIFF_FORMAT.RENDERED));
  $('#revision-rendered').hidden = REV.format !== DIFF_FORMAT.RENDERED;
  mdcDrawNav();
  $('#revision-view').dataset.format = REV.format;
  $('#revision-pdf').hidden = REV.format !== DIFF_FORMAT.PDF;
  $('#revision-source').hidden = REV.format !== DIFF_FORMAT.SOURCE;
  $('#revision-overlay').hidden = $('#revision-side').hidden = REV.format !== DIFF_FORMAT.OVERLAY;
  if (REV.overlay)
    $('#revision-status').textContent = REV.format === DIFF_FORMAT.OVERLAY ? overlayStatus(REV.overlay) : '';
}
/** Switch formats while retaining comparison scale for the selected commit. */
function setRevisionFormat(format) {
  REV.format = revisionFormatFor(format, !!REV.overlay, isMdDoc(), mdcDrawn());
  drawRevisionFormat();
  if (REV.format === DIFF_FORMAT.RENDERED && REV.commit) {
    if (MDC.key !== revKey()) mdcShow(REV.commit, REV.base, REV.seq, DOC);
    else $('#revision-status').textContent = MDC.line;
    // a range's list painting and its last-seen count come with its source diff's answer: read it beside the compare
    if (REV.base && REV.sourceCommit !== revKey()) loadRevisionSource(REV.commit, REV.seq, DOC);
  }
  if (REV.format === DIFF_FORMAT.SOURCE && !REV.base && mdcDrawn()) $('#revision-status').textContent = '';
  if (REV.format === DIFF_FORMAT.SOURCE && REV.commit && REV.sourceCommit !== revKey())
    loadRevisionSource(REV.commit, REV.seq, DOC);
  if (REV.format === DIFF_FORMAT.SOURCE && REV.base && REV.sourceCommit === revKey())
    $('#revision-status').textContent = REV.rangeLine;
  // The comparison PDF is only built when that format is actually viewed - [변경 보기] and a range go straight to the source diff, so neither wastes a latexdiff build.
  if (REV.format === DIFF_FORMAT.PDF && REV.commit && REV.pdfCommit !== revKey()) {
    REV.pdfCommit = revKey();
    $('#revision-status').textContent = '비교 PDF 상태를 확인하는 중입니다.';
    loadRevisionPdf(REV.commit, REV.seq, DOC);
  }
  syncRevisionWhole();
  drawRevisionZoom();
  if (revisionPdfActive()) resizeRevisionPdf();
  if (REV.format === DIFF_FORMAT.OVERLAY && REV.target) scrollOverlayTo(REV.target.page);
  if (REV.target) revTargetNote();
}
// Shows the manuscript or the changes view: the nav bar's tabs, the navigation sheet's switch and the phone's position button
// ([변경사항 ▾] in the changes view) follow; leaving the changes view forgets the pin it was opened for and redraws the pages.
// The mark badges' press areas are measured again as the pages show (markHitSides: marks drawn meanwhile had no boxes).
function setViewMode(mode) {
  const revisions = mode === VIEW_MODE.REVISIONS;
  if (!revisions && document.body.classList.contains('revision-open')) leaveRevisions();
  if (revisions && !document.body.classList.contains('revision-open')) keepSpot(); // the pages are still drawn: the spot the way back returns to
  document.body.classList.toggle('revision-open', revisions);
  $('#view-manuscript').setAttribute('aria-pressed', String(!revisions));
  $('#view-revisions').setAttribute('aria-pressed', String(revisions));
  if (!revisions) {
    REV.target = null;
    mdcClear();
  }
  if (revisions) loadRevisions();
  else {
    ++REV.seq;
    clearRevisionPdf();
    setRevisionOverlay(null);
    $('#revision-pin').hidden = true;
    revTargetActs();
    boundK();
    returnToSpot();
    if (VEC.doc) vecSchedule(0);
    updateSectionStrip();
    markHitSides();
  }
  drawNavView();
  drawPos();
  searchOffer(); // the changes view has no search
}
// Reads the document's recent commits into the changes view. Without history (not Git, a view-only PDF, no recent commit, or
// more history files than the server names one by one: reason too_many_files) the one reason line stays and the unusable
// [변경 PDF] [소스 diff] and the comparison note are hidden; a pin's guide line stays.
// A figure document's answer carries its two builds (overlay): its [겹쳐 보기] takes the place of [변경 PDF] and opens first,
// with or without history; its [소스 diff] shows only with history.
async function loadRevisions() {
  const seq = ++REV.seq,
    k = DOC,
    list = $('#revision-list'),
    out = $('#revision-diff'),
    tg = REV.target,
    again = !tg && REV.rowsDoc === k && REV.rows.length > 0;
  clearRevisionPdf();
  list.hidden = false;
  list.textContent = '최근 변경사항을 읽는 중입니다.';
  out.textContent = '';
  $('#revision-pin').hidden = !tg;
  if (tg) revTargetNote('변경사항을 읽는 중입니다.');
  else revTargetActs();
  let data;
  try {
    data = (await api(dq('/api/revisions?limit=' + REVISION_PAGE, k), { what: '변경사항 읽기', silent: true })).data;
  } catch (e) {
    if (seq === REV.seq) list.textContent = '변경사항을 읽지 못했습니다.';
    return;
  }
  if (seq !== REV.seq || k !== DOC) return;
  const rows = (data.available ? data.revisions : []),
    kept = REV.range;
  REV.rows = rows;
  REV.rowsDoc = k || '';
  REV.more = !!data.more;
  if (!again) REV.listOpen = false;
  if (!again || !REV.seen || REV.seenState !== SEEN_STATE.OK) openSeen(revSeen(k || ''), rows);
  REV.history = !!data.available && rows.length > 0;
  setRevisionOverlay(data.overlay || null);
  const fig = !!REV.overlay;
  REV.format = revisionFormatFor(REV.format, fig, isMdDoc(), mdcDrawn());
  drawRevisionFormat(); // a LaTeX document after a figure leaves the overlay; a Markdown one opens its rendered compare, a text one its source diff
  $('#revision-controls').hidden = !REV.history && !fig;
  $('#revision-note').hidden = !REV.history;
  $('#revision-pdf-tab').hidden = fig || isMdDoc();
  $('#revision-overlay-tab').hidden = !fig;
  $('#revision-source-tab').hidden = !REV.history;
  $('#revision-rendered-tab').hidden = !REV.history || !mdcDrawn();
  if (!data.available) {
    list.textContent =
      data.reason === 'too_many_files'
        ? tl('이 문서는 이력 파일이 {n}개를 넘어 Git 변경사항을 볼 수 없습니다.', { n: data.limit })
        : '이 문서의 Git 변경사항을 볼 수 없습니다.';
    drawRange();
    if (fig) {
      setRevisionFormat(DIFF_FORMAT.OVERLAY);
      return;
    }
    if (tg)
      revTargetNote(
        tg.region
          ? '보기 전용 PDF 문서의 핀이라 Git 변경사항이 없습니다 — 고친 곳은 LaTeX 문서(본문 등)의 변경사항에서 찾으세요.'
          : '이 문서는 Git 이력을 읽을 수 없어(Git 저장소가 아니거나 경로가 밖) 핀 자리를 변경과 맞출 수 없습니다.',
      );
    return;
  }
  if (!rows.length) {
    list.textContent = '이 문서의 최근 변경사항이 없습니다.';
    drawRange();
    if (fig) setRevisionFormat(DIFF_FORMAT.OVERLAY);
    else if (tg) revTargetNote('이 문서의 최근 12개 커밋에 변경이 없습니다.');
    return;
  }
  list.hidden = true;
  list.textContent = '';
  // A pin's commit is picked by the server's rule over the same window (api.md §두 커밋 사이): a hash anywhere in it, a PR
  // number or the lines in its first rows.
  if (tg) {
    if (REV.seenState === SEEN_STATE.PENDING) resolveSeen(k || '', rows[0].id);
    const pick = await pickRevisionFor(tg, seq, k);
    if (seq !== REV.seq || k !== DOC || REV.target !== tg) return;
    tg.commit = pick.id;
    tg.via = pick.via;
    tg.hit = pick.hit;
    REV.range = { mode: RANGE_MODE.ONE, start: pick.id, end: pick.id, endSet: false };
    // a figure's lines and pictures are both exact: its overlay opens first; a LaTeX pin's lines exist only in the source
    // diff, and a Markdown pin's own hunks too - its [그린 비교] beside it compares the whole commit (ADR-0031 D6)
    if (fig) showRevision(pick.id, DIFF_FORMAT.OVERLAY);
    else showRevision(pick.id, DIFF_FORMAT.SOURCE);
    drawRange();
    return;
  }
  // Opened by a document's update message (updates.js openUpdateRange): the commits it named - after the last seen one (base)
  // up to the newest it named (top; the newest row without one) - as a range in the source diff, the list painting what the
  // server says the range holds. Commits above top (the checkout ahead of the shown build, one come since) stay out, also
  // when the list is read again for a new build: the range keeps the message's base and its end (endSet).
  const want = REV.want;
  REV.want = null;
  if (want && want.base && !fig) {
    const at = (id) => rows.findIndex((r) => r.id === id || r.id.startsWith(id)),
      i = at(want.base),
      j = want.top ? at(want.top) : 0;
    const top = j >= 0 ? rows[j].id : want.top,
      base = i >= 0 ? rows[i].id : want.base;
    if (top !== base && !(i >= 0 && j > i)) {
      REV.range = { mode: RANGE_MODE.FROM, start: i > 0 && i > j ? rows[i - 1].id : top, end: top, endSet: true, base };
      showRange(REV.range);
      return;
    }
  }
  // The same document read again while the view is open (a new build) keeps the range shown, moved to the newest commit
  // unless its end was chosen (endSet: pressed, or named by an update message); a range comes back in its source diff, so a
  // new build never starts its comparison PDF (only [변경 PDF] does).
  // A message's range is its base and end, whatever page of rows is read: thirty newer commits push its start off the
  // first page, and the server still compares them while they are in its history window (else its refusal shows).
  const held = !!kept && kept.mode === RANGE_MODE.FROM && !!kept.base && kept.endSet;
  if (again && (held || rows.some((r) => r.id === kept.start))) {
    if (REV.seenState === SEEN_STATE.OK && kept.mode !== RANGE_MODE.LAST) resolveSeen(k || '', rows[0].id);
    showRange(kept.mode === RANGE_MODE.ONE ? kept : { ...kept, end: kept.endSet ? kept.end : rows[0].id }, REV.format);
    return;
  }
  if (REV.seenState === SEEN_STATE.PENDING && !fig) {
    showRange(rangeMode(rows, REV.range, RANGE_MODE.LAST, REV.seen));
    return;
  }
  if (REV.seenState === SEEN_STATE.PENDING) resolveSeen(k || '', rows[0].id);
  const id = rows.some((r) => r.id === REV.commit) ? REV.commit : rows[0].id;
  REV.range = { mode: RANGE_MODE.ONE, start: id, end: id, endSet: false };
  showRevision(id, fig ? DIFF_FORMAT.OVERLAY : undefined);
  drawRange();
}
// ------------------------------------------------ Comparing two commits (issue #188, docs/handbook/viewer.md §변경 보기)
// The quick range [마지막으로 본 뒤 N | 이 커밋부터 | 이 커밋만] (#revision-range) and the commit list that stays on screen
// (#revision-commits). The rules below are pure functions of the loaded rows (newest first); showRange() shows their request.
// What is painted and counted comes from the server's range answer (commit_ids, commits): a range follows ancestry, which the
// list's positions do not show (a merged line, a base on another line, a pull that merged older commits).

/** The range after a row press (id): in [이 커밋만] that commit alone; otherwise that commit to the newest - except that, right
 * after such a press, a newer row ends the range there, and the start pressed again is that commit alone. Pure. */
function rangePress(rows, rg, id) {
  const at = (x) => rows.findIndex((r) => r.id === x),
    newest = rows.length ? rows[0].id : id;
  if (rg.mode === RANGE_MODE.ONE) return { mode: RANGE_MODE.ONE, start: id, end: id, endSet: false };
  if (rg.mode === RANGE_MODE.FROM && id === rg.start)
    return { mode: RANGE_MODE.FROM, start: id, end: id, endSet: true };
  if (rg.mode === RANGE_MODE.FROM && !rg.endSet && at(id) >= 0 && at(id) < at(rg.start))
    return { mode: RANGE_MODE.FROM, start: rg.start, end: id, endSet: true };
  return { mode: RANGE_MODE.FROM, start: id, end: newest, endSet: false };
}
/** The range after a segment press: [마지막으로 본 뒤] the last-seen commit to the newest; [이 커밋부터] the commit in focus to
 * the newest; [이 커밋만] the commit in focus alone (the newest after [마지막으로 본 뒤]). Pure. */
function rangeMode(rows, rg, mode, seen) {
  const newest = rows.length ? rows[0].id : rg.end;
  if (mode === RANGE_MODE.LAST) return { mode, start: newest, end: newest, endSet: false };
  const focus = rg.mode === RANGE_MODE.LAST && mode === RANGE_MODE.ONE ? rg.end : rg.start;
  return { mode, start: focus, end: mode === RANGE_MODE.FROM ? newest : focus, endSet: false };
}
/** What a range asks the server: {commit, base}, base '' for one commit against its first parent. [마지막으로 본 뒤] compares
 * the last-seen commit with the newest; [이 커밋부터] the start's first parent with the end - a start that is the end, or a
 * root commit (no parent), is that commit alone - or, for the range an update message opened, its base (the last seen
 * commit, rg.base) with the end. Pure. */
function rangeRequest(
  rows,
  rg,
  seen,
) {
  if (rg.mode === RANGE_MODE.LAST && seen) return { commit: rg.end, base: seen.id };
  if (rg.mode === RANGE_MODE.FROM && rg.base) return { commit: rg.end, base: rg.base };
  if (rg.mode !== RANGE_MODE.FROM || rg.start === rg.end) return { commit: rg.start, base: '' };
  const s = rows.find((r) => r.id === rg.start);
  return s && s.parents.length ? { commit: rg.end, base: s.parents[0] } : { commit: rg.start, base: '' };
}
/** The commits the list paints for request req: one commit itself; a range the commits the server's answer names (ids,
 * its commit_ids), none while that answer is unknown. Pure. */
function paintedIds(req, ids) {
  return req.base ? (ids || []).slice() : [req.commit];
}
/** The rows of merged lines: those between a merge and its first parent, when that parent is loaded. Pages come in ancestry
 * order (the server's --topo-order), so a merged line's commits sit right below their merge; a merge whose first parent is
 * not loaded marks nothing. Pure. */
function sideRows(rows) {
  const out = new Set();
  rows.forEach((r, i) => {
    if (r.parents.length < 2) return;
    const j = rows.findIndex((x) => x.id === r.parents[0]);
    for (let k = i + 1; k < j; k++) out.add(rows[k].id);
  });
  return out;
}
// The key a source diff or comparison PDF was loaded for: the commit, or base..commit for a range.
function revKey() {
  return REV.base ? REV.base + '..' + REV.commit : REV.commit;
}
// Shows range rg: opens what it asks, then draws the picker - a range always in its source diff (its comparison PDF is built
// only when [변경 PDF] is pressed, whatever format was shown), one commit as a list choice always opened (format undefined:
// the comparison PDF of a LaTeX document, the format shown of a figure document). A Markdown document keeps the tab shown,
// for a range too: its rendered compare builds nothing (md-compare.js).
function showRange(rg, format) {
  REV.range = rg;
  const q = rangeRequest(REV.rows, rg, REV.seen);
  const drawn = mdcDrawn() ? (REV.format === DIFF_FORMAT.SOURCE ? DIFF_FORMAT.SOURCE : DIFF_FORMAT.RENDERED) : '';
  showRevision(
    q.commit,
    drawn || (q.base ? (format === DIFF_FORMAT.OVERLAY ? format : DIFF_FORMAT.SOURCE) : format),
    q.base,
  );
  drawRange();
}
// A row of the list pressed (rangePress) and a quick-range segment pressed (rangeMode).
function pressRevisionRow(id) {
  if (id) showRange(rangePress(REV.rows, REV.range, id));
}
function setRevisionRange(mode) {
  if (!REV.rows.length || mode === REV.range.mode) return;
  showRange(rangeMode(REV.rows, REV.range, mode, REV.seen));
}
// Draws the quick range: the pressed segment, and [마지막으로 본 뒤 N] - hidden without a record of this document in this
