    SEARCH.open && !s.hidden && BAND !== LAYOUT_BAND.PHONE && box.getClientRects().length
      ? box.getBoundingClientRect()
      : null;
  if (!b) return; // closed: nothing is measured
  const cs = getComputedStyle(nav),
    gap = parseFloat(cs.columnGap) || 0,
    keep = [],
    off = [],
    left = [];
