    if (!isRegion(d) && suggestForSave(SG, suggestOff(d, META ? META.kind : undefined))) {
      done();
      bannerNote(
        NOTICE_HOST.COMPOSER,
        tr('연결이 끊겨 제안 수정은 쌓아 둘 수 없습니다 — [제안 수정]을 끄면 메모만 쌓아 둡니다'),
        NOTICE_KIND.ERR,
        null,
        { save: true, source: 'POST /api/pin' },
      );
      return;
    }
