      restored = restoredDraftOwns(draft);
    if (cleared) {
      COMPOSE.box = null;
      cancelSelection(true);
      if (box) box.remove();
      syncDraft();
    } // a saved pin leaves no draft
    else if (restored) {
      cancelSelection(true);
      syncDraft();
    } else clearSavedDraft(draft);
