  held: 0,
  flushing: false,
  prep: false,
  saidStale: false,
  boot: true,
  idem: false,
  staleNote: null,
  db: null,
  following: false,
  kept: undefined,
  keptAt: 0,
  seen: {},
  timer: undefined,
  fails: 0,
  after: 0,
  failSaid: false,
  holder: false,
  me: '',
