    kind: 'region',
    page: r.page,
    frac: r.frac,
    quote,
    file: null,
    name: null,
    lo: null,
    hi: null,
    pdf: META ? META.pages_build : null,
    pdf_build: r.pdf_build,
    doc: r.doc || DOC,
    offline: true,
    rect,
    levels: [],
    overlaps: [],
