// A rival edit wrote another note while card E was open (E.theirs): the banner shows that note whole and offers
// [내 메모로 덮어쓰기]; the card keeps the person's text, and [저장] alone does not write over theirs.
function editTheirs(E) {
  const theirs = E.theirs == null ? '' : E.theirs;
  bannerNote(
    NOTICE_HOST.LIST,
    tl('핀 #{id} 메모를 저장하지 않았습니다 · 그사이 다른 곳에서 메모가 바뀌었습니다', { id: E.id }) +
      ' — ' +
      tl('지금 메모: {note}', { note: theirs || tr('(빈 메모)') }),
    NOTICE_KIND.WARN,
    {
      label: '내 메모로 덮어쓰기',
      tip: '지금 메모를 읽은 뒤, 카드의 메모로 바꿉니다',
      fn: () => {
        if (!editorOwns(E)) return;
        E.overwrite = true;
        saveEdit();
      },
    },
    { source: 'POST /api/pins/' + E.id + '/edit edit', literal: true },
  );
}
// An edit the server answered 409 suggest_base_changed: nothing was saved and card E keeps its draft. The editor shows the lines'
// current text against the draft and the list's banner offers [지금 원문으로 맞추기] (the draft keeps its text and takes that text as
// its base); then [저장] again.
function editSuggestRefused(E, data) {
  if (editorOwns(E)) {
    E.sg.current = {
      text: String(data.current || ''),
      file: E.file || null,
      lo: E.lo,
      hi: E.hi,
    };
    renderEdit();
  }
  bannerNote(
    NOTICE_HOST.LIST,
    tl('핀 #{id} 수정 실패', { id: E.id }) + ' — ' + tr('그사이 그 줄들의 원문이 바뀌었습니다'),
    NOTICE_KIND.ERR,
    {
      label: '지금 원문으로 맞추기',
      tip: '쓰던 글은 그대로 두고, 이 제안이 바꿀 원문을 지금 그 줄들의 글로 바꿉니다. 그다음 다시 저장합니다',
      fn: () => {
        if (editorOwns(E))
          suggestRebase(
            E.sg,
            E,
            () => editorOwns(E),
            () => {
              if (editorOwns(E)) renderEditSuggest(E);
            },
          );
      },
    },
    { source: 'POST /api/pins/' + E.id + '/edit edit' },
  );
}

// ------------------------------------------------ Re-place location
// Shows the re-place banner with markup (Html) as its content.
function banner(markup) {
  const b = $('#banner');
  setHtml(b, markup);
  b.hidden = false;
}
function bannerRepick(err) {
  if (!REPICK) return;
  const line = err ? html`<span class="errline flush">${err}</span>` : '';
  banner(
    html`<span>${isMdDoc() ? tl('핀 #{id} 의 새 위치를 문서에서 고르세요 · Esc 취소', { id: REPICK.id }) : tl('핀 #{id} 의 새 위치를 PDF에서 드래그하세요 · Esc 취소', { id: REPICK.id })}</span>${line}<span class="sp"></span><button class="btn-sm" data-act="rp-cancel" data-tip="위치 다시 잡기를 그만둡니다 (Esc)">취소</button>`,
  );
}
// The re-place banner compares the current and the new place (lines as the composer writes them, rng: L9, L3-L5); on a figure
