  const visit = captureVisit(),
    E = EDITOR.current;
  let loc = {
    file: c.file,
    page: c.page,
    lo: lv.lo,
    hi: lv.hi,
    raw_lo: c.raw_lo,
    raw_hi: c.raw_hi,
    via: c.via,
    score: c.score,
    fill: c.fill,
    rival: c.rival,
    frac: c.frac,
    pdf_build: c.pdf_build || undefined,
    quote: c.quote,
    scope: lv.level || null,
    kind: lv.level ? kindFor(lv.level, lv.env) : c.kind,
  };
